/bin/zsh -lc "node --input-type=module <<'RELAYER_GRAPH_PROGRAM'
import {RelayerGraphClient,NodeObject,EdgeObject,LayerObject,NodePlacementObject,LayerLayoutObject,html,css,detailCapability} from 'file:///Users/[redacted]/Desktop/relayer-graphcomplete/packages/graph-client/dist/index.js';
const graph=RelayerGraphClient.fromEnv();
await graph.getNode(36);await graph.getNeighbors(36);const current=await graph.getCurrent();
const style=css"'`
.page {font-family:system-ui;line-height:1.55;padding:24px;max-width:850px;margin:auto;color:var(--ink);background-color:var(--surface);}
[data-relayer-theme="light"] .page {--ink:#20313d;--surface:#fafbf9;--muted:#526572;--border:#c9d5da;--accent:#165a73;--tint:#eaf3f5;}
[data-relayer-theme="dark"] .page {--ink:#edf3f5;--surface:#171e24;--muted:#b3c3cc;--border:#465963;--accent:#8bd5ed;--tint:#22343e;}
h1 {font-size:26px;line-height:1.2;margin:0 0 16px;} h2 {font-size:18px;margin:0 0 5px;}
p {margin:8px 0;} .eyebrow {font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--accent);font-weight:700;margin-bottom:12px;}
.stage {display:grid;grid-template-columns:36px 1fr;gap:12px;border:1px solid var(--border);border-radius:8px;padding:12px;margin:8px 0;}
.num {font-weight:700;color:var(--accent);font-size:22px;} .out {font-size:14px;color:var(--accent);}
.arrow {color:var(--accent);margin-left:28px;line-height:1;}
.note {font-size:14px;color:var(--muted);margin-top:16px;}
.formula {padding:16px;background-color:var(--tint);border-left:3px solid var(--accent);}
table {border-collapse:collapse;width:100%;margin:14px 0;font-size:14px;} th,td {border-bottom:1px solid var(--border);padding:10px;text-align:left;vertical-align:top;} th {color:var(--accent);}
nav {display:flex;flex-wrap:wrap;gap:8px;margin-top:16px;}
button {padding:10px 14px;border:1px solid var(--accent);border-radius:7px;color:var(--ink);background-color:var(--tint);font:inherit;text-align:left;}
button:hover {border-width:2px;padding:9px 13px;} button:focus-visible {outline:3px solid var(--accent);outline-offset:3px;}
code {font-size:14px;overflow-wrap:anywhere;}
`;
const rootNode=new NodeObject('"'brain','Transformer training map','Raw text → curated corpus → token sequences → pretrained weights → optional post-training → evaluation and deployment. A conceptual map of the common decoder-only language-model pipeline.','concept','training-overview');
const data=new NodeObject('database','Text and tokens','Data provenance, filtering, leakage prevention, tokenization, and training-sequence construction.','concept','data-detail');
const learn=new NodeObject('brain','The learning loop','Causal attention, next-token cross-entropy, backpropagation, and training at scale.','concept','learn-detail');
const release=new NodeObject('rocket','Post-training and release','Instruction tuning, preference optimization, release evaluation, and inference serving.','concept','release-detail');
const layer=(n,k)=>{const l=new LayerObject([n],[],new LayerLayoutObject([new NodePlacementObject(n,0.5,0.5)],'default'),k);l.defaultNode=n;return l;};
const root=layer(rootNode,'training-root');
const children=[layer(data,'data-layer'),layer(learn,'learn-layer'),layer(release,'release-layer')];
const actions=children.map((target,i)=>({kind:'navigate',relation:'expand',sourceLayer:root,label:['Text and token details','Inside the learning loop','Post-training and release'][i],icon:['database','brain','rocket'][i],target,clientKey:['data-expand','learn-expand','release-expand'][i]}));
rootNode.detailAuthoring.setComponent('main',html"'`<main class="page"><div class="eyebrow">From raw text through deployment</div><h1>Training turns text into model weights</h1><p>The common decoder-only language-model pipeline follows this sequence. Each stage produces the artifact used by the next.</p>
<section class="stage"><div class="num">1</div><div><h2>Prepare text</h2><p>Collect text with appropriate provenance and usage rights. Normalize, filter, and deduplicate it; keep evaluation data separate.</p><div class="out">Output: curated corpus</div></div></section><div class="arrow" aria-hidden="true">↓</div>
<section class="stage"><div class="num">2</div><div><h2>Tokenize and batch</h2><p>Encode text as token IDs. Build context windows with shifted next-token targets and appropriate masks.</p><div class="out">Output: training sequences</div></div></section><div class="arrow" aria-hidden="true">↓</div>
<section class="stage"><div class="num">3</div><div><h2>Pretrain</h2><p>A causal transformer predicts the next token. Measure prediction loss, backpropagate, update weights, and repeat across many batches.</p><div class="out">Output: base-model checkpoint + tokenizer</div></div></section><div class="arrow" aria-hidden="true">↓</div>
<section class="stage"><div class="num">4</div><div><h2>Post-train · optional</h2><p>Train on desired instruction-response examples. Preference optimization may further adapt behavior using feedback.</p><div class="out">Output: model adapted to its intended use</div></div></section><div class="arrow" aria-hidden="true">↓</div>
<section class="stage"><div class="num">5</div><div><h2>Evaluate, deploy, monitor</h2><p>Check quality, robustness, privacy, and harmful behavior. Validate serving optimizations, release with rollback, and monitor real usage.</p><div class="out">Output: versioned model service</div></div></section>
<p class="note">Evaluation happens throughout; failures can send work back to earlier stages. Next-token training does not guarantee factuality or reliable behavior. Normal inference uses weights without updating them; feedback can inform a later training run. This is a conceptual map, not a report of a training run.</p>
<nav aria-label="Technical explanations"><button gc=${detailCapability.expand('"'data-control',actions[0])}>Text and token details</button><button gc="'${detailCapability.expand('"'learn-control',actions[1])}>Inside the learning loop</button><button gc="'${detailCapability.expand('"'release-control',actions[2])}>Post-training and release</button></nav></main>"'`,style);
data.detailAuthoring.setComponent('"'main',html"'`<main class="page"><div class="eyebrow">Technical detail · Data</div><h1>Text → token sequences</h1><table><thead><tr><th>Step</th><th>What matters</th></tr></thead><tbody><tr><td>Document sources</td><td>Record provenance, permitted uses, dates, languages, quality filters, and mixture weights. Data selection affects coverage and bias.</td></tr><tr><td>Filter and deduplicate</td><td>Remove malformed or unwanted content and exact/near duplicates. Quality filters can change which groups and domains are represented.</td></tr><tr><td>Prevent leakage</td><td>Separate related documents or sources before constructing windows. Check overlap with evaluation sets; random token-level splits can leak nearly identical content.</td></tr><tr><td>Choose a tokenizer</td><td>Learn or select a vocabulary, often subword pieces or bytes. Tokens are not necessarily words. Vocabulary size affects sequence length and compute.</td></tr><tr><td>Build sequences</td><td>Split, truncate, or pack token streams to a context limit. Apply padding, boundary, attention, and loss masks according to the recipe.</td></tr></tbody></table><h2>Shift the targets by one position</h2><div class="formula"><code>Input: [A, B, C] → Targets: [B, C, D]</code></div><p>One training pass scores many next-token positions in parallel, while causal masking limits each position to its permitted prefix.</p><p class="note">A document-boundary token alone does not prevent attention across packed documents. Keep the tokenizer and special-token conventions with the model weights: token IDs have model-specific meanings.</p></main>`,style);
learn.detailAuthoring.setComponent('"'main',html"'`<main class="page"><div class="eyebrow">Technical detail · Pretraining</div><h1>Predict → loss → gradients → update</h1><p>The objective is to make each observed next token likely given its prefix.</p><div class="formula"><code>L(θ) = − (1 / N) Σₜ log pθ(xₜ | x₍&lt;t₎)</code><p class="note">θ denotes model weights. N counts scored tokens; padding and other excluded positions are masked out.</p></div><table><thead><tr><th>Operation</th><th>Mechanism</th></tr></thead><tbody><tr><td>Forward pass</td><td>Token embeddings and positional information enter repeated transformer blocks. Multi-head causal attention mixes allowed prefix information; feed-forward networks transform representations. A vocabulary head produces logits, and softmax defines token probabilities.</td></tr><tr><td>Measure loss</td><td>Next-token cross-entropy compares predictions with actual token IDs. Teacher forcing supplies the true prefix during training.</td></tr><tr><td>Backpropagate</td><td>Automatic differentiation computes loss gradients for trainable parameters.</td></tr><tr><td>Update weights</td><td>An optimizer such as AdamW adjusts weights, usually with a learning-rate schedule and gradient clipping. Repeat over the training-token budget.</td></tr></tbody></table><h2>Training at scale</h2><p>Mixed precision, gradient accumulation, data/model parallelism, and activation checkpointing help fit large runs into available hardware. Track validation performance, numerical stability, throughput, and resumable checkpoints.</p><h2>Training versus generation</h2><p>Training scores known tokens in parallel under a causal mask. Generation repeatedly selects a new token and appends it to the prefix, usually reusing cached attention keys and values.</p><p class="note">Architecture and optimization recipes vary. Lower held-out loss is useful evidence, but does not fully measure task usefulness, truthfulness, or safety.</p></main>`,style);
release.detailAuthoring.setComponent('"'main',html"'`<main class="page"><div class="eyebrow">Technical detail · Behavior and release</div><h1>Base model → deployed assistant</h1><table><thead><tr><th>Stage</th><th>Typical mechanism</th><th>Key check</th></tr></thead><tbody><tr><td>Supervised fine-tuning</td><td>Next-token loss on desired instruction-response examples; many recipes score assistant-response tokens only.</td><td>Example quality, coverage, and capability regressions.</td></tr><tr><td>Preference optimization</td><td>RLHF can train a reward model from comparisons, then optimize the policy. DPO directly optimizes preferred versus rejected responses using a reference policy.</td><td>Reward exploitation, feedback bias, and unintended behavior changes.</td></tr><tr><td>Release evaluation</td><td>Held-out benchmarks, application tests, adversarial probes, and human review; check contamination and report uncertainty.</td><td>Defined quality/risk thresholds for the complete system.</td></tr><tr><td>Serving</td><td>Load weights with the correct tokenizer, chat format, and decoding settings. Use batching and attention caches; optional quantization reduces resource use.</td><td>Quality after optimization, memory, latency, throughput, and load behavior.</td></tr><tr><td>Operation</td><td>Version artifacts, stage rollout, monitor failures, and retain rollback capability.</td><td>Privacy-aware feedback collection and evaluation before subsequent releases.</td></tr></tbody></table><p class="note">These are common options, not a mandatory recipe. Retrieval, tools, prompts, and guardrails are application components; adding them does not necessarily retrain the model. Evaluation continues after deployment and cannot prove correctness for every input.</p></main>`,style);
for(const n of [rootNode,data,learn,release]){await graph.checkpointNodeDetail(n);const r=await graph.submitNode(n);console.log('"'NODE',n.title,r.preview?.path??r.preview?.status);}
for(const l of [...children,root]){const r=await graph.submitLayer(l);console.log('LAYER',l.clientKey,r.preview?.path??r.preview?.status);}
for(const a of actions)await graph.addAction(rootNode,a);
await graph.addAction(36,{kind:'navigate',relation:'expand',label:'Transformer training map',icon:'brain',target:root,clientKey:'root-response'});
// FINAL_SUBMISSION
RELAYER_GRAPH_PROGRAM"

