release.detailAuthoring.setComponent('main',html`<main class="page"><div class="eyebrow">Technical detail · Behavior and release</div><h1>Base model → deployed assistant</h1><table><thead><tr><th>Stage</th><th>Typical mechanism</th><th>Key check</th></tr></thead><tbody><tr><td>Supervised fine-tuning</td><td>Next-token loss on desired instruction-response examples; many recipes score assistant-response tokens only.</td><td>Example quality, coverage, and capability regressions.</td></tr><tr><td>Preference optimization</td><td>RLHF can train a reward model from comparisons, then optimize the policy. DPO directly optimizes preferred versus rejected responses using a reference policy.</td><td>Reward exploitation, feedback bias, and unintended behavior changes.</td></tr><tr><td>Release evaluation</td><td>Held-out benchmarks, application tests, adversarial probes, and human review; check contamination and report uncertainty.</td><td>Defined quality/risk thresholds for the complete system.</td></tr><tr><td>Serving</td><td>Load weights with the correct tokenizer, chat format, and decoding settings. Use batching and attention caches; optional quantization reduces resource use.</td><td>Quality after optimization, memory, latency, throughput, and load behavior.</td></tr><tr><td>Operation</td><td>Version artifacts, stage rollout, monitor failures, and retain rollback capability.</td><td>Privacy-aware feedback collection and evaluation before subsequent releases.</td></tr></tbody></table><p class="note">These are common options, not a mandatory recipe. Retrieval, tools, prompts, and guardrails are application components; adding them does not necessarily retrain the model. Evaluation continues after deployment and cannot prove correctness for every input.</p></main>`,style);
for(const n of [rootNode,data,learn,release]){await graph.checkpointNodeDetail(n);const r=await graph.submitNode(n);console.log('NODE',n.title,r.preview?.path??r.preview?.status);}
for(const l of [...children,root]){const r=await graph.submitLayer(l);console.log('LAYER',l.clientKey,r.preview?.path??r.preview?.status);}
for(const a of actions)await graph.addAction(rootNode,a);
await graph.addAction(36,{kind:'navigate',relation:'expand',label:'Transformer training map',icon:'brain',target:root,clientKey:'root-response'});
// FINAL_SUBMISSION
RELAYER_GRAPH_PROGRAM

